#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/types.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// ColorPicker's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/color_picker.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The picked colour; a change raises value_changed. Picking writes it; a program's write moves the thumbs (the hue is kept when the colour is grey).
template <typename Declaring>
struct ColorPickerValueCapability {
    PropertyCell<Color, ColorPickerValueCapability<Declaring>> value{Color::rgba(255, 255, 255)};

    static void assign(ColorPickerValueCapability& capability, Color incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.value), incoming);
        if (!capability.value.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.value));
    }
};

// Whether the alpha track is shown and the alpha can be picked; hiding it leaves the value's alpha as it is.
template <typename Declaring>
struct ColorPickerAlphaEnabledCapability {
    PropertyCell<bool, ColorPickerAlphaEnabledCapability<Declaring>> alpha_enabled{true};

    static void assign(ColorPickerAlphaEnabledCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.alpha_enabled), incoming);
        if (!capability.alpha_enabled.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.alpha_enabled));
    }
};

// Every ColorPicker capability, in the order the declaring class takes them.
template <typename Declaring>
struct ColorPickerCapabilities : public ColorPickerValueCapability<Declaring>,
                                 public ColorPickerAlphaEnabledCapability<Declaring> {};

} // namespace gui_forms
